// Build lookup by Item Ref from BOQ-item-match tab (matches mail SOR e.g. 72EL841007 -> 841007)
function normBoqItemRefKey(raw) {
  if (raw === null || raw === undefined) return null;
  const digits = String(raw).replace(/[^0-9]/g, '');
  if (!digits) return null;
  const last6 = digits.length >= 6 ? digits.slice(-6) : digits.padStart(6, '0');
  return String(parseInt(last6, 10));
}

