    if (typeof t === 'object' && t !== null) return t;
    if (typeof t === 'string') { try { return JSON.parse(t); } catch (e) {} }
  }
  const cc = r?.message?.content ?? r?.choices?.[0]?.message?.content ?? null;
  if (cc !== null) {
    if (typeof cc === 'object') return cc;
    if (typeof cc === 'string') { try { return JSON.parse(cc); } catch (e) {} }
