  const m = String(s).match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})\s+(\d{1,2}):(\d{2})/);
  if (!m) return null;
  let [, d, mo, y, h, mi] = m;
  if (y.length === 2) y = (parseInt(y, 10) >= 70 ? '19' : '20') + y;
