  const precheckNames = ['PreCheck WI vs Export', 'PreCheck WI vs Export1'];
  let precheckItems = [];
  for (const nn of precheckNames) {
    try {
      precheckItems = $(nn).all();
      if (precheckItems.length) break;
    } catch (e) {}
  }
  rows = precheckItems.map((i) => {
    const j = i.json || {};
    const woe = j.works_order_extracted || {};
    const mid = j.id != null ? String(j.id) : (j.messageId != null ? String(j.messageId) : null);
    const isDup = !!(j._precheck_in_template || j._skip_ai_pre);
    return {
      categories: j.categories ?? null,
      receivedDateTime: j.receivedDateTime ?? null,
      hasAttachments: j.hasAttachments ?? null,
      subject: j.subject ?? null,
      bodyPreview: j.bodyPreview ?? null,
      body_plain_text: j.body_plain_text ?? null,
      client_order_reference: j._precheck_client_order_ref ?? null,
      works_order_ref: woe.works_order_ref ?? null,
      repair_type: woe.repair_type ?? null,
      uprn: woe.uprn ?? null,
      order_type: isDup ? 'duplicate' : (j._precheck_is_variation ? 'variation' : (j._precheck_is_new_order ? 'new' : 'non_duplicate')),
      is_duplicate: isDup,
      cor_in_export: !!j._precheck_cor_in_export,
      duplicate_reason: j._precheck_duplicate_reason ?? null,
      graph_message_id: mid,
    };
  });
}

const orders = rows.filter((o) => o.subject || o.body_plain_text || o.graph_message_id);
const duplicate_orders = orders.filter((o) => o.is_duplicate);
const processed_orders = orders.filter((o) => !o.is_duplicate);

return [{
  json: {
    _debug_aggregate: true,
    summary: {
      total: orders.length,
      duplicate_count: duplicate_orders.length,
      non_duplicate_count: processed_orders.length,
      new_count: processed_orders.filter((o) => o.order_type === 'new').length,
      variation_count: processed_orders.filter((o) => o.order_type === 'variation').length,
    },
    orders,
    duplicate_orders,
    non_duplicate_orders: processed_orders,
  },
}];

const staticData = $getWorkflowStaticData('global');
const batch = Array.isArray(staticData.wiEmailBatch) ? staticData.wiEmailBatch : [];
const count = batch.length;
return [{ json: { has_import_rows: count > 0, import_count: count } }];
